function allTags(){ const m=new Map(); bookmarks.forEach(b=>b.tags.forEach(t=>m.set(t,(m.get(t)||0)+1))); return [...m.entries()].sort((a,b)=>b[1]-a[1]); }

// ---- query parser: words, "phrases", #tags, AND/OR/NOT, parentheses, implicit AND ----
function tokenize(s){
  const toks=[]; const re=/\s*(\(|\)|"[^"]*"|#[^\s()]+|[^\s()]+)/g; let m;
  while((m=re.exec(s))!==null){ let t=m[1];
    const up=t.toUpperCase();
    if(t==='('||t===')') toks.push({k:t});
    else if(up==='AND'||up==='OR'||up==='NOT') toks.push({k:up});
    else if(t[0]==='#') toks.push({k:'term', tag:t.slice(1).toLowerCase()});
    else if(t[0]==='"') toks.push({k:'term', text:t.slice(1,-1).toLowerCase()});
    else toks.push({k:'term', text:t.toLowerCase()});
  }
  return toks;
}
// grammar: OR > AND > NOT > primary ; implicit AND between adjacent operands
function parseQuery(s){
  const toks=tokenize(s); let i=0;
  const peek=()=>toks[i], next=()=>toks[i++];
  function primary(){
    const t=peek(); if(!t) throw 0;
    if(t.k==='('){ next(); const e=orExpr(); if(!peek()||peek().k!==')') throw 0; next(); return e; }
    if(t.k==='term'){ next(); return t.tag!==undefined ? b=>b.tags.includes(t.tag)
                                                        : b=>hay(b).includes(t.text); }
    throw 0;
  }
  function notExpr(){ if(peek()&&peek().k==='NOT'){ next(); const e=notExpr(); return b=>!e(b); } return primary(); }
  function isOperandStart(t){ return t&&(t.k==='term'||t.k==='('||t.k==='NOT'); }
  function andExpr(){ let l=notExpr();
    while(peek()&&(peek().k==='AND'||isOperandStart(peek()))){ if(peek().k==='AND') next(); const r=notExpr(); const a=l,b2=r; l=b=>a(b)&&b2(b); }
    return l; }
  function orExpr(){ let l=andExpr(); while(peek()&&peek().k==='OR'){ next(); const r=andExpr(); const a=l,b2=r; l=b=>a(b)||b2(b); } return l; }
  if(toks.length===0) return {ok:true, pred:()=>true};
  try{ const e=orExpr(); if(i!==toks.length) throw 0; return {ok:true, pred:e}; }
  catch(_){ return {ok:false}; }
}
function hay(b){ return [b.url,b.title,b.desc,b.note].join('\n').toLowerCase(); }

let compiled={ok:true, pred:()=>true};
function matches(b){
