// ---- tag chip input ----
function tagEditor(initial){
  const wrap=document.createElement('div'); wrap.className='taginput';
  const tags=[...initial];
  const input=document.createElement('input'); input.placeholder=tags.length?'add a tag…':'type a tag and press Enter';
  let sug=null, active=-1, cands=[];
  function draw(){ [...wrap.querySelectorAll('.tag')].forEach(n=>n.remove());
    tags.forEach((t,i)=>{ const s=document.createElement('span'); s.className='tag'; s.innerHTML=`${escapeHtml(t)} <span class="x">×</span>`;
      s.querySelector('.x').addEventListener('click',()=>{ tags.splice(i,1); draw(); }); wrap.insertBefore(s,input); }); }
  function add(v){ v=v.trim().toLowerCase().replace(/,$/,''); if(v&&!tags.includes(v)) tags.push(v); input.value=''; draw(); closeSug(); }
  function closeSug(){ if(sug){ sug.remove(); sug=null; } active=-1; cands=[]; }
  function showSug(){
    const q=input.value.trim().toLowerCase();
    const existing=allTags().map(([t])=>t).filter(t=>!tags.includes(t));
    cands = q ? existing.filter(t=>t.includes(q)) : existing;
    closeSug(); if(!cands.length && !q) return;
    sug=document.createElement('div'); sug.className='suggest';
    cands.slice(0,6).forEach((t,idx)=>{ const d=document.createElement('div'); d.textContent=t;
      d.addEventListener('mousedown',e=>{ e.preventDefault(); add(t); }); sug.appendChild(d); });
    if(q && !existing.includes(q)){ const d=document.createElement('div'); d.className='new'; d.textContent=`Create new tag “${q}”`;
      d.addEventListener('mousedown',e=>{ e.preventDefault(); add(q); }); sug.appendChild(d); }
    wrap.parentElement.appendChild(sug); active=-1;
  }
  function move(dir){ const items=sug?[...sug.children]:[]; if(!items.length) return;
    items.forEach(x=>x.classList.remove('active')); active=(active+dir+items.length)%items.length; items[active].classList.add('active'); }
